# Independent Julia GPU local-spin/exchange oracle (#572 milestone 1).
#
#   julia +1.13.1 --startup-file=no --project=extern/Julia-mVMC/test/gpu \
#     gpu/mvmc-gpu-cuda/tests/fixtures/localspin/gen_localspin_julia.jl \
#     INPUT/namelist.def OUTPUT.txt opt|physcal
#
# Follows the Julia GPU namelist runners (ext/cuda_runners.jl) stage by stage:
# XORWOW initialization with local spins, the runner's sampling cache
# (Opt: delayed queue and paired inverse at 2Ne >= 128; PhysCal: immediate),
# measurement, then a deterministic supplied tape through the cached sampler
# with the runner's exchange probability and options, and measurement again.
# Opt additionally dumps derivatives and one direct SR update plus gauge.
using CUDA, MVMCOptimizers, LinearAlgebra, SHA
CUDA.device!(0); CUDA.allowscalar(false); BLAS.set_num_threads(1)
const GPU = Base.get_extension(MVMCOptimizers, :MVMCCUDAExt)
input, output, flavor = abspath(ARGS[1]), ARGS[2], ARGS[3]
flavor in ("opt", "physcal") || error("flavor must be opt or physcal")
physcal = flavor == "physcal"
data, _ = GPU.prepared_gpu_data(input; seed=79, physcal)
GPU.validate_cuda_data(data)
walkers = 8
ex = GPU.exchange_probability(data)
s, pf = GPU.initial_gpu_state(data, walkers; seed=79, return_pfaffians=true,
    needs_derivatives=!physcal)
cache = GPU.GPUSamplingCache(s; delayed=!physcal && GPU.supports_delayed_sampling(s))
inverse = !physcal && 2s.nelec >= 128 ? GPU.PairedSamplingInverse(s) : GPU.BatchedSamplingInverse(s)
GPU.refresh_sampling_state!(s, cache, inverse; initial_pfaffians=pf)
GPU.validate_initial_walkers(s, s.configurations)
o = GPU.CUDAObservables(s, data; measure_greens=physcal)
sr = physcal ? nothing : GPU.CUDASR(s, data)
steps = 3 * s.nsite
tape = reshape([UInt32((UInt64(k) * 0x9e3779b97f4a7c15 + 0xbf58476d1ce4e5b9) >> 32)
                for k in 1:5walkers*steps], 5, walkers, steps)
println("Julia=", VERSION, " CUDA=", pkgversion(CUDA), " curand=", CUDA.cuRAND.version(),
    " cublas=", CUDA.cuBLAS.version(), " cusolver=", CUDA.CUSOLVER.version(),
    " input_sha256=", join([bytes2hex(sha256(read(joinpath(dirname(input), f)))) for f in sort(readdir(dirname(input)))], ","), " exchange=", ex,
    " delayed=", cache.updates !== nothing, " triangle=", 2s.nelec >= 128)
open(output, "w") do io
    function dump(name, x)
        v = vec(Array(x)); println(io, name, " ", length(v)); foreach(a -> println(io, a), v)
    end
    function stage(prefix)
        MVMCOptimizers.gpu_observables!(s, o; sampling_cache=cache)
        dump(prefix * "_values", o.values)
        if !physcal
            GPU.derivatives!(s, sr, o)
            dump(prefix * "_derivatives", sr.derivatives)
        end
    end
    dump("exchange", [ex])
    dump("parameters", s.parameters)
    dump("initial_cfg", s.configurations)
    dump("initial_pf", cache.pfaffians)
    stage("initial")
    # The tape is a fixed formula (regenerated by the Rust test); record its
    # first words and a wrapping word sum instead of every word.
    dump("tape_head", vec(tape)[1:20])
    dump("tape_sum", [sum(UInt64.(vec(tape))) % UInt64(2)^32])
    MVMCOptimizers.gpu_sample!(s; steps, tape=CuArray(tape), exchange_fraction=ex, cache,
        empty_destinations=true, incremental_correlation=true, triangle_update=2s.nelec >= 128)
    dump("final_cfg", s.configurations)
    dump("accepted", s.accepted)
    dump("final_pf", cache.pfaffians)
    dump("final_overlaps", s.overlaps)
    stage("final")
    if !physcal
        moments = GPU.sr_moments(sr, copy(vec(view(o.values, 1, :))))
        solver = GPU.CUDASRSolver(length(s.parameters))
        GPU.resident_sr_update!(s, sr, moments, data.modpara, solver)
        GPU.sync_gpu_parameters!(s, GPU.CUDAParameterGauge(data))
        GPU.check_sr_solver(solver)
        dump("parameters_after", s.parameters)
        dump("energy_mean", moments.meanE)
    end
end
CUDA.synchronize()
println("wrote ", output)
